import {api,el,loadAssets,displayURL,signout} from './display-api.mjs';
const $=s=>document.querySelector(s),dialog=$('#createDialog'),form=$('#createForm');
$('#createDisplay').onclick=()=>{dialog.showModal();form.elements.name.focus()};$('.dialog-close').onclick=()=>dialog.close();
form.elements.type.onchange=()=>{$('#cabinetOptions').hidden=form.elements.type.value!=='cabinet'};
form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;$('#createStatus').textContent='Creating…';try{const body={action:'create'};for(const k of ['name','type','frame','defaultFinish','populate'])body[k]=form.elements[k].value;const display=await api('displays',{method:'POST',body:JSON.stringify(body)});location.href=displayURL(display)}catch(e){$('#createStatus').textContent=e.message;button.disabled=false}};
async function start(){const [p,displays]=await Promise.all([api('profile'),api('displays')]);window.edgeProfile=p;window.dispatchEvent(new CustomEvent('edge:profile',{detail:p}));$('#collectionTools').hidden=false;$('#displayLibrary').hidden=false;$('#libraryStatus').textContent='';signout();
 if(!displays.length){$('#displayCards').append(el('p','Your first display starts here. Choose a cabinet, floating rocks or pillars.','empty-displays'));return}
 const {catalog,assets}=await loadAssets();for(const d of displays){const link=el('a',undefined,'display-card');link.href=displayURL(d);const preview=el('div',undefined,'display-cover '+d.type);preview.dataset.frame=d.frame;
 for(const [n,id] of d.previews.entries()){const slot=el('span',undefined,'cover-slot');if(d.type==='rocks'){const rock=new Image();rock.src='/assets/floating-rock-v1.webp';rock.alt='';rock.className='cover-rock';slot.append(rock)}if(d.type==='pillars'){const column=el('span',undefined,'cover-pillar');slot.append(column)}const img=new Image();img.alt='';img.loading='lazy';img.src=assets[id]?.src||catalog.get(id)?.img||'';img.className='cover-piece';slot.append(img);preview.append(slot)}if(!d.previews.length)preview.append(el('span',d.type==='rocks'?'◇':'▤','cover-empty'));
 link.append(preview,el('h2',d.name),el('p',(d.type==='pillars'?'Pillars · Prototype':d.type==='rocks'?'Floating rocks · Prototype':'Cabinet')+' · '+d.count+' '+(d.count===1?'piece':'pieces')));$('#displayCards').append(link)}
}
start().catch(e=>{$('#libraryStatus').textContent=e.status===401?'':e.message;if(e.status===401)$('#loginPanel').hidden=false});
